import json

# Load stats
with open('/app/output/computed_stats.json') as f:
    stats = json.load(f)

# Read SVGs
svgs = {}
for name in ['svg_global_trend', 'svg_mf_ratio', 'svg_age_profile', 'svg_top10', 'svg_changes', 'svg_decades', 'svg_age_sex']:
    with open(f'/app/output/{name}.svg') as f:
        svgs[name] = f.read()

# Build HTML report
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</title>
<style>
  :root {{
    --primary: #1e3a5f;
    --secondary: #c44e52;
    --accent: #4c72b0;
    --teal: #55a868;
    --gray: #6b7280;
    --light-gray: #f3f4f6;
    --dark: #111827;
    --white: #ffffff;
  }}
  * {{ box-sizing: border-box; }}
  body {{
    font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--dark);
    background: var(--light-gray);
    margin: 0;
    padding: 0;
    line-height: 1.6;
  }}
  .container {{
    max-width: 1100px;
    margin: 0 auto;
    background: var(--white);
    padding: 40px 48px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.06);
  }}
  header {{
    border-bottom: 4px solid var(--primary);
    padding-bottom: 24px;
    margin-bottom: 32px;
  }}
  h1 {{
    font-size: 2rem;
    font-weight: 700;
    color: var(--primary);
    margin: 0 0 8px 0;
