    text-align: center;
    box-shadow: 0 2px 8px rgba(30,58,95,0.18);
  }}
  .kpi-card.accent {{ background: linear-gradient(135deg, var(--accent) 0%, #3b5c9e 100%); }}
  .kpi-card.teal {{ background: linear-gradient(135deg, var(--teal) 0%, #3d8a5a 100%); }}
  .kpi-card.secondary {{ background: linear-gradient(135deg, var(--secondary) 0%, #a33d41 100%); }}
  .kpi-value {{
    font-size: 1.9rem;
    font-weight: 700;
